import { getDocument, listDocumentKeys } from '../../utils/aws/s3.js';

/**
 * An AWS account a business has handed us for measurement.
 */
export class MeteredAccount {
    /**
     * The account the metering role lives in.
     * @example "445566778899"
     */
    public accountId: string;
    /**
     * The role we assume to read the account.
     * @example "arn:aws:iam::445566778899:role/metering-metering"
     */
    public roleArn: string;
    /**
     * The external id the role's trust policy asks for, when it asks for one.
     */
    public externalId?: string;
    /**
     * The region the business runs the metered workload in.
     * @example "us-east-1"
     */
    public region: string;
}

/**
 * One of the accounts a customer has been onboarded onto.
 */
export class CustomerAccountOnboarding {
    /**
     * The account the customer's workload runs in.
     * @example "445566778899"
     */
    public accountId: string;
    /**
     * True when the account exists solely for this customer, meaning every
     * metered resource found in it belongs to them no matter how it is tagged.
     */
    public dedicated?: boolean;
}

/**
 * The per customer onboarding record kept in the business' metering bucket,
 * one object per customer under {@link MeteringRegistry.customerRecordPrefix}.
 * Only customers with a record here are billable.
 */
export class CustomerOnboardingRecord {
    public customerId: string;
    public displayName?: string;
    public accounts: Array<CustomerAccountOnboarding>;
}

/**
 * The tenancy of a single metered account, resolved from the customer
 * onboarding records.
 */
export class AccountTenancy {
    /**
     * Every customer genuinely onboarded for the account.
     */
    public tenants: Array<string> = [];
    /**
     * Set when the account is dedicated to exactly one customer.
     */
    public dedicatedTo?: string;

    public get isDedicated(): boolean {
        return !!this.dedicatedTo;
    }
}

/**
 * The onboarding record a business keeps in its metering bucket. It is written
 * by the onboarding flow and read by every collector that has to sweep more
 * than one account.
 */
export class MeteringRegistry {
    private static readonly logger = new Logger(MeteringRegistry.name);

    public businessID: string;
    /**
     * Key prefix the per customer onboarding records sit under in the same
     * bucket, one object per customer.
     * @example "onboarding/customers/"
     */
    public customerRecordPrefix: string;
    public accounts: Array<MeteredAccount>;

    static async load(bucket: string, key: string): Promise<MeteringRegistry> {
        return getDocument<MeteringRegistry>(bucket, key);
    }

    /**
     * Reads every per customer onboarding record living beside the registry.
     * These records are the only source of truth for who may be billed.
     */
    static async loadCustomerRecords(
        bucket: string,
        customerRecordPrefix: string,
    ): Promise<Array<CustomerOnboardingRecord>> {
        if (!customerRecordPrefix) {
            MeteringRegistry.logger.warn('No customer record prefix on the metering registry, nothing is billable');
            return [];
        }
        const keys = await listDocumentKeys(bucket, customerRecordPrefix);
        const records = await Promise.all(
            keys.map(async (key) => {
                try {
                    return await getDocument<CustomerOnboardingRecord>(bucket, key);
                } catch (e) {
                    MeteringRegistry.logger.error(`Couldn't read customer onboarding record ${key}`, e);
                    return undefined;
                }
            }),
        );
        return records.filter((record) => record && record.customerId);
    }

    /**
     * Works out, per account, who is onboarded for it and whether the account
     * is dedicated to a single customer.
     */
    static resolveTenancy(records: Array<CustomerOnboardingRecord>): Record<string, AccountTenancy> {
        const tenancyByAccount: Record<string, AccountTenancy> = {};
        const dedicatedClaims: Record<string, Array<string>> = {};
        (records ?? []).forEach((record) => {
            (record.accounts ?? []).forEach((entry) => {
                // Older records list the accounts as bare account ids
                const account: CustomerAccountOnboarding =
                    typeof entry === 'string' ? { accountId: entry } : (entry as CustomerAccountOnboarding);
                if (!account?.accountId) {
                    return;
                }
                const accountId = String(account.accountId);
                const tenancy = tenancyByAccount[accountId] ?? new AccountTenancy();
                if (!tenancy.tenants.includes(record.customerId)) {
                    tenancy.tenants.push(record.customerId);
                }
                tenancyByAccount[accountId] = tenancy;
                if (account.dedicated) {
                    dedicatedClaims[accountId] = (dedicatedClaims[accountId] ?? []).concat(record.customerId);
                }
            });
        });
        Object.keys(dedicatedClaims).forEach((accountId) => {
            const claims = dedicatedClaims[accountId];
            if (claims.length === 1) {
                tenancyByAccount[accountId].dedicatedTo = claims[0];
            } else {
                // Two customers can't both own an account outright, so treat it as shared.
                MeteringRegistry.logger.warn(
                    `Account ${accountId} is claimed as dedicated by several customers, treating it as shared`,
                );
            }
        });
        Object.keys(tenancyByAccount).forEach((accountId) => {
            tenancyByAccount[accountId].tenants.sort();
        });
        return tenancyByAccount;
    }
}
